@page "/notifications"
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc
@rendermode InteractiveServer

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <span>@n.Message</span>
                    <br />
                    <small class="text-muted">@n.Timestamp.ToString("yyyy-MM-dd HH:mm:ss") UTC</small>
                </div>
                <span class="badge bg-secondary">@n.Id</span>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    // Runs during both static SSR and interactive render.
    // Loads the initial data so it appears in the first server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationSvc.GetAll();
        _lastCheck = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // Only called once when the component becomes interactive (not during static SSR).
    // This is the safe place to start the background polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate potential new data arriving server-side
            NotificationSvc.SimulateIncoming();

            var newer = NotificationSvc.GetSince(_lastCheck);
            if (newer.Count > 0)
            {
                _lastCheck = newer.Max(n => n.Timestamp);
                _notifications.InsertRange(0, newer);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

