namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
    public bool IsRead { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();
    private readonly Random _random = new();

    private static readonly string[] SampleMessages =
    [
        "Your build completed successfully.",
        "New comment on pull request #42.",
        "Deployment to staging finished.",
        "CI pipeline failed for branch 'feature/auth'.",
        "You were mentioned in issue #108.",
        "Security scan found 0 vulnerabilities.",
        "New team member joined the project.",
        "Release v2.1.0 was published.",
        "Database migration applied successfully.",
        "Scheduled maintenance window starts in 1 hour."
    ];

    public NotificationService()
    {
        var now = DateTime.UtcNow;
        for (var i = 0; i < 5; i++)
        {
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = SampleMessages[i],
                Timestamp = now.AddMinutes(-(5 - i)),
                IsRead = false
            });
        }
    }

    /// <summary>Returns all notifications ordered by newest first.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications.OrderByDescending(n => n.Timestamp)];
        }
    }

    /// <summary>Returns notifications created after the given timestamp.</summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return [.. _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)];
        }
    }

    /// <summary>
    /// Simulates new incoming notifications (~40 % chance per call).
    /// </summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            if (_random.NextDouble() < 0.4)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = SampleMessages[_random.Next(SampleMessages.Length)],
                    Timestamp = DateTime.UtcNow,
                    IsRead = false
                });
            }
        }
    }
}

